/bin/zsh -lc "python3 - <<'PY'
import itertools, json
with open('task.json') as f:
    task=json.load(f)
V=task['payload']['vertices']
E={tuple(sorted(e)) for e in task['payload']['edges']}
best=[]
for r in range(len(V)+1):
    for S in itertools.combinations(V,r):
        ok=True
        for i in range(r):
            for j in range(i+1,r):
                if tuple(sorted((S[i],S[j]))) in E:
                    ok=False; break
            if not ok: break
        if ok and r>len(best):
            best=list(S)
print(len(best), best)
PY"

